<?php\n\ndeclare(strict_types=1);\n\nnamespace App\\Tests\\Service\\Notification;\n\nuse App\\Entity\\NotificationEvent;\nuse App\\Entity\\RadarMedidor;\nuse App\\Repository\\NotificationEventRepository;\nuse App\\Service\\Notification\\EmailNotificationService;\nuse App\\Service\\Notification\\NotificationTriggerService;\nuse PHPUnit\\Framework\\TestCase;\n\nfinal class NotificationTriggerServiceTest extends TestCase\n{\n    public function testSuppressesRepeatedRadarUpdate(): void\n    {\n        $events = $this->createMock(NotificationEventRepository::class);\n        $events->method('findRecent')->willReturn(new NotificationEvent('radar_atualizado', 'Radar atualizado', 'Alteração'));\n\n        $email = $this->createMock(EmailNotificationService::class);\n        $email->expects(self::never())->method('dispatch');\n\n        $service = new NotificationTriggerService($email, $events);\n        $radar = $this->createMock(RadarMedidor::class);\n        $radar->method('getId')->willReturn(10);\n\n        self::assertNull($service->radarUpdated($radar, ['situacao' => ['pendente', 'aprovado']]));\n    }\n\n    public function testDispatchesRadarUpdateForRelevantChange(): void\n    {\n        $events = $this->createMock(NotificationEventRepository::class);\n        $events->method('findRecent')->willReturn(null);\n\n        $email = $this->createMock(EmailNotificationService::class);\n        $email->expects(self::once())->method('dispatch')->willReturn(\n            new NotificationEvent('radar_atualizado', 'Radar atualizado', 'Alteração')\n        );\n\n        $service = new NotificationTriggerService($email, $events);\n        $radar = $this->createMock(RadarMedidor::class);\n        $radar->method('getId')->willReturn(10);\n\n        self::assertNotNull($service->radarUpdated($radar, ['situacao' => ['pendente', 'aprovado']]));\n    }\n\n    public function testIgnoresIrrelevantRadarChange(): void\n    {\n        $events = $this->createMock(NotificationEventRepository::class);\n        $events->expects(self::never())->method('findRecent');\n\n        $email = $this->createMock(EmailNotificationService::class);\n        $email->expects(self::never())->method('dispatch');\n\n        $service = new NotificationTriggerService($email, $events);\n        $radar = $this->createMock(RadarMedidor::class);\n        $radar->method('getId')->willReturn(10);\n\n        self::assertNull($service->radarUpdated($radar, ['capacidade' => ['10', '20']]));\n    }\n}\n